// ── Bar Mgmt: Feedback Notify — payload normalizer ──────────
// Receives POST from src/lib/notify.ts (createFeedback action)
// Payload: { type, title, description, venueName, source, sentAt, screenshotDataUrl? }
// Some n8n versions wrap the body under `.body`, others flatten it —
// handle both (same defensive pattern used in w3-assessment-intake.json).
// screenshotDataUrl is OPTIONAL — only present when Pablo pasted a screenshot.
// ─────────────────────────────────────────────────────────────

const body = $input.first().json.body || $input.first().json;

const type              = body.type              || 'OTHER';
const title             = body.title             || '(sin título)';
const description       = body.description       || '';
const venueName         = body.venueName         || 'Bar Management';
const sentAt            = body.sentAt            || new Date().toISOString();
const screenshotDataUrl = body.screenshotDataUrl || null;

const message = `New feedback on ${venueName}\n\n${type} — ${title}\n\n${description}`;

return [{
  json: { message, type, title, description, venueName, sentAt, screenshotDataUrl, hasScreenshot: !!screenshotDataUrl }
}];

// Turns the base64 data: URI (FeedbackItem.screenshotDataUrl) into real
// binary so the Telegram node can send it as a photo, not just a text link.
// Client-side compression already caps this at roughly 1000px wide / JPEG
// q0.75 (see src/app/(dashboard)/feedback/FeedbackClient.tsx), so it should
// always be small enough for a normal sendPhoto call.

const item = $input.first();
const dataUrl = item.json.screenshotDataUrl;

const match = /^data:(.+);base64,(.*)$/.exec(dataUrl);
if (!match) {
  // Malformed data URL — fall back to text-only rather than fail the run.
  return [{ json: { ...item.json, hasScreenshot: false } }];
}

const mimeType = match[1];
const base64 = match[2];
const buffer = Buffer.from(base64, 'base64');

return [{
  json: item.json,
  binary: {
    data: await this.helpers.prepareBinaryData(buffer, 'feedback-screenshot.jpg', mimeType)
  }
}];
